<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import EcButton from '../components/EcButton.vue';
import ProbabilityBar from '../components/ProbabilityBar.vue';
import SectionHeader from '../components/SectionHeader.vue';
import { formatAmount, useFinanceStore } from '../stores/finance.js';
import { useActivityV2Store } from '../stores/activityV2.js';
import { activityDisplayStatusLabel, bucketLabel, marketDisplayStatusLabel } from '../utils/display.js';
const router=useRouter(); const finance=useFinanceStore(); const activityStore=useActivityV2Store();
const clock=ref(Date.now()); const clockTimer=setInterval(()=>{clock.value=Date.now()},30000);
onBeforeUnmount(()=>clearInterval(clockTimer));
onMounted(()=>Promise.all([finance.refresh(),activityStore.refresh()]));
const categoryNames=computed(()=>Object.fromEntries(finance.categories.map(x=>[x.id,x.name])));
const marketCards=computed(()=>finance.markets.map((market)=>{const activity=activityStore.activities.find(x=>x.id===market.eventId);return{...market,title:activity?.title||market.eventId||market.marketId}}));
const upcoming=computed(()=>activityStore.activities.filter(x=>!['CANCELLED','COMPLETED'].includes(x.status)).sort((a,b)=>new Date(a.startsAt)-new Date(b.startsAt)).slice(0,3));
const paidTotal=computed(()=>Object.values(finance.wallet?.categories||{}).reduce((s,x)=>s+Number(x.paid?.available||0),0));
const bonusTotal=computed(()=>Object.values(finance.wallet?.categories||{}).reduce((s,x)=>s+Number(x.bonus?.available||0),0));
const probabilities=(market)=>market.outcomes.map(o=>({...o,pct:(market.outcomeProbabilityBps?.[o.id]||0)/100}));
const shortTime=(value)=>new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
</script>
<template><div class="home">
  <section class="hero"><div><p class="kicker">校园体育 · 封闭积分</p><h1>赛事、积分与活动<br>汇入同一条可信链路</h1><p class="hero-copy">用 B_bonus 参与预测，用 B_paid 兑换真实服务；公开市场只展示五分钟取整快照，个人仓位保留在私有集合。</p><div class="hero-actions"><EcButton variant="ink" size="sm" @click="router.push('/tickets')">查看活动票务</EcButton><EcButton variant="outline" size="sm" @click="router.push('/wallet')">管理 A / B</EcButton></div></div>
    <aside class="balance-panel"><p>我的封闭积分 · A</p><strong>{{ finance.aBalance }}</strong><small>A 可用</small><div><span><b>{{ formatAmount(paidTotal) }}</b><em>B_paid</em></span><span><b>{{ formatAmount(bonusTotal) }}</b><em>B_bonus</em></span></div></aside>
  </section>
  <div class="trust-strip"><span>◆ 组织级私有数据</span><span>◷ 收益等待 7 天后成熟</span><span>⚖ 挑战与仲裁</span><span>↻ 到期与销毁规则</span></div>
  <div class="home-grid"><section class="markets"><SectionHeader kicker="公开快照" title="预测市场进度" :meta="`${marketCards.length} 个市场`" :rule="true" />
    <div class="market-list"><button v-for="(market,index) in marketCards" :key="market.marketId" class="market-row" @click="router.push(`/event/${market.marketId}`)"><span class="index">{{ String(index+1).padStart(2,'0') }}</span><span class="market-copy"><em>{{ categoryNames[market.categoryId]||market.categoryId }} · {{ marketDisplayStatusLabel(market,clock) }}</em><b>{{ market.title }}</b><small>{{ bucketLabel(market.stakeBucket) }} · 池 {{ formatAmount(market.displayedPool) }} · 上限 {{ formatAmount(market.marketCap) }}</small></span><ProbabilityBar class="market-probability" :outcomes="probabilities(market)" /></button></div>
    <p v-if="!finance.loading&&!marketCards.length" class="empty">当前没有市场</p>
  </section><aside class="sidebar"><section><SectionHeader kicker="近期安排" title="近期活动" :size="20"/><div class="upcoming"><button v-for="item in upcoming" :key="item.id" @click="router.push('/tickets')"><span><b>{{ item.title }}</b><small>{{ activityDisplayStatusLabel(item,clock) }} · {{ shortTime(item.startsAt) }}</small></span><em>{{ item.applicationCount }}/{{ item.capacity }}</em></button><p v-if="!upcoming.length" class="empty">暂无近期活动</p></div></section><section class="privacy"><i>◈</i><h3>隐私说明</h3><p>这里不展示个人下注记录、精确余额或实时资金流。只显示有延迟和取整后的市场快照。</p></section></aside></div>
</div></template>
<style scoped>
.home{width:min(1180px,100%);margin:0 auto;padding-bottom:48px}.hero{padding:clamp(30px,5vw,56px) clamp(20px,4vw,48px) 30px;border-bottom:2px solid var(--ec-ink);display:block}.kicker{color:var(--ec-red);font:700 10px var(--ec-font-mono);letter-spacing:.14em;margin-bottom:13px}.hero h1{font-size:clamp(40px,5vw,54px);line-height:1.02;letter-spacing:-.03em}.hero-copy{color:var(--ec-ink-2);font-size:14.5px;line-height:1.75;max-width:720px;margin-top:18px}.hero-actions{display:flex;gap:10px;margin-top:20px}.balance-panel{max-width:520px;background:#eef5fc;border:1px solid #c8dff3;border-left:5px solid var(--ec-red);border-radius:var(--ec-r-panel);padding:24px 22px;color:var(--ec-ink);margin-top:28px}.balance-panel p{font:500 10px var(--ec-font-mono);letter-spacing:.12em;color:var(--ec-muted)}.balance-panel>strong{display:block;font:800 56px/1 var(--ec-font-display);color:var(--ec-red);margin-top:8px}.balance-panel>small{color:var(--ec-muted);font:500 10px var(--ec-font-mono)}.balance-panel>div{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:16px}.balance-panel span{background:rgba(255,255,255,.75);border:1px solid rgba(0,113,227,.12);border-radius:var(--ec-r-field);padding:11px 12px}.balance-panel b,.balance-panel em{display:block}.balance-panel b{font:700 24px var(--ec-font-display)}.balance-panel em{font:500 9px var(--ec-font-mono);color:var(--ec-muted);font-style:normal}.trust-strip{display:flex;gap:clamp(16px,3vw,26px);padding:12px clamp(20px,4vw,48px);border-bottom:1px solid var(--ec-line);color:var(--ec-muted);font:500 10px var(--ec-font-mono);white-space:nowrap;overflow:auto;scrollbar-width:none}.trust-strip::-webkit-scrollbar{display:none}.home-grid{display:block}.markets{padding:30px clamp(20px,4vw,48px) 40px}.market-list{margin-top:6px;max-width:1040px}.market-row{width:100%;display:grid;grid-template-columns:48px minmax(0,1fr) minmax(220px,280px);gap:18px;align-items:center;padding:18px 4px;border:0;border-bottom:1px solid var(--ec-line);background:transparent;text-align:left;cursor:pointer}.market-row:hover{background:var(--ec-inset)}.index{font:800 30px var(--ec-font-display);color:var(--ec-faint-2)}.market-copy>*{display:block}.market-copy em{color:var(--ec-red);font:600 10px var(--ec-font-mono);font-style:normal}.market-copy b{font:700 21px/1.2 var(--ec-font-display);margin-top:6px}.market-copy small{color:var(--ec-muted);font:500 10px var(--ec-font-mono);margin-top:9px}.sidebar{padding:0 clamp(20px,4vw,48px);display:grid;gap:32px}.upcoming{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-top:12px}.upcoming button{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px;border:1px solid var(--ec-line);border-radius:11px;background:transparent;text-align:left;cursor:pointer}.upcoming button:hover{background:var(--ec-inset)}.upcoming b,.upcoming small{display:block}.upcoming b{font:700 16px var(--ec-font-display)}.upcoming small{font:500 9px var(--ec-font-mono);color:var(--ec-faint);margin-top:4px}.upcoming em{color:var(--ec-red);font:700 11px var(--ec-font-mono);font-style:normal}.privacy{background:#f2f2f5;border:1px solid var(--ec-line);border-radius:var(--ec-r-card);padding:22px;color:var(--ec-ink)}.privacy i{color:var(--ec-red);font-size:22px;font-style:normal}.privacy h3{font-size:20px;margin:7px 0}.privacy p{color:var(--ec-muted);font-size:12.5px;line-height:1.65}.empty{padding:22px;text-align:center;color:var(--ec-faint);font-size:12px}
@media(max-width:900px){.market-row{grid-template-columns:42px minmax(0,1fr) minmax(180px,240px)}}
@media(max-width:700px){.markets{padding-top:24px}.market-row{grid-template-columns:34px 1fr}.market-probability{grid-column:2}.upcoming{grid-template-columns:1fr}.sidebar{padding-bottom:8px}}
@media(max-width:480px){.hero{padding-top:28px}.hero h1{font-size:clamp(34px,9.4vw,38px)}.hero-actions{flex-wrap:wrap}.balance-panel{margin-top:24px}.market-row{gap:12px}}
</style>
